def summarize(rows):
    passed = sum(1 for row in rows if row['status'] == 'pass')
    elapsed = sum(row['seconds'] for row in rows if row['status'] == 'pass')
    return {'passed': passed, 'elapsed_seconds': elapsed, 'passes_per_hour': passed * 3600 / elapsed if elapsed else None}

