import unittest
from metrics import summarize

class MetricsTests(unittest.TestCase):
    def test_all_attempts_contribute_time(self):
        result = summarize([{'status': 'pass', 'seconds': 10}, {'status': 'error', 'seconds': 20}])
        self.assertEqual(result['elapsed_seconds'], 30)
        self.assertEqual(result['passes_per_hour'], 120)

    def test_no_elapsed(self):
        self.assertIsNone(summarize([])['passes_per_hour'])

if __name__ == '__main__':
    unittest.main()
